import hashlib

def fixed_chunk_hashes(data: bytes, size: int = 4096) -> list[str]:
    return [hashlib.sha256(data[i:i+size]).hexdigest() for i in range(0, len(data), size)]

GEAR_TABLE = [(i * 0x9E3779B97F4A7C15) & 0xFFFFFFFFFFFFFFFF for i in range(256)]

def fastcdc_cut_points(data: bytes, min_sz: int = 2048, max_sz: int = 16384, mask: int = 0x1FFF) -> list[int]:
    cuts, start, h = [], 0, 0
    n = len(data)
    for i, b in enumerate(data):
        h = ((h << 1) + GEAR_TABLE[b]) & 0xFFFFFFFFFFFFFFFF
        length = i - start + 1
        if length >= min_sz and ((h & mask) == 0 or length >= max_sz):
            cuts.append(i + 1)
            start, h = i + 1, 0
    if start < n:
        cuts.append(n)
    return cuts

def negotiate_missing_chunks(block_index, chunk_hashes: list[str]) -> list[str]:
    existing = block_index.batch_exists(chunk_hashes)
    return [h for h in chunk_hashes if h not in existing]

def sweep_orphan_chunks(db, s3, grace_days: int = 7):
    candidates = db.fetch_unreferenced_older_than(days=grace_days)
    for chunk_hash in candidates:
        if db.try_lock_for_gc(chunk_hash):
            s3.delete_object(Key=f'blocks/{chunk_hash}')
            db.delete_chunk_row(chunk_hash)

def commit_file_revision(db, file_id: str, expected_rev: int, new_chunks: list[str], device: str) -> dict:
    current = db.get_file_head(file_id)
    if current['rev'] != expected_rev:
        fork_id = db.create_conflict_fork(file_id, device, new_chunks)
        return {'status': 'CONFLICT_FORKED', 'fork_id': fork_id}
    new_rev = db.advance_revision(file_id, expected_rev, new_chunks)
    return {'status': 'COMMITTED', 'rev': new_rev}
